const items = $input.all();

const totalIngresos = items.reduce((sum, i) => sum + parseFloat(i.json.ingresos_totales), 0);

const filasHTML = items.map(i => `
    <tr>
        <td><b>${i.json.categoria}</b></td>
        <td>${i.json.total_ventas}</td>
        <td>${i.json.unidades_vendidas}</td>
        <td>Q${parseFloat(i.json.ingresos_totales).toFixed(2)}</td>
        <td>${i.json.porcentaje_ingresos}%</td>
    </tr>
`).join('');

const telegramMsg = ` Ventas por categoría

${items.map(i =>
    `▪️ ${i.json.categoria}\n   Ventas: ${i.json.total_ventas} | Ingresos: Q${parseFloat(i.json.ingresos_totales).toFixed(2)} | ${i.json.porcentaje_ingresos}%`
).join('\n')}

Total general: Q${totalIngresos.toFixed(2)}`;

return [{
    json: {
        filas_html: filasHTML,
        total_ingresos: totalIngresos.toFixed(2),
        telegram: telegramMsg
    }
}];
